import{_ as l,C as r,o as e,c as d,a3 as s,j as i,E as t,a as n}from"./chunks/framework.C6R8kWFE.js";const f=JSON.parse('{"title":"9-dars (Mentor). IP manzillash, Subnetting va tarmoq diagnostikasi vositalari","description":"","frontmatter":{"title":"9-dars (Mentor). IP manzillash, Subnetting va tarmoq diagnostikasi vositalari","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"10-sinf (DevOps)","link":"/mentor/10-sinf-devops/"},"week":{"n":3,"link":"/mentor/10-sinf-devops/hafta-03/"},"g":9,"title":"IP manzillash, Subnetting va tarmoq diagnostikasi vositalari","lead":"Tarmoq muhandisligi asoslari: IPv4 va IPv6, qism tarmoqlarni hisoblash (Subnetting, CIDR) hamda nosozliklarni aniqlovchi qurollar (ping, traceroute, ss, curl).","slide":"/slaydlar/10-sinf-devops/hafta-03/dars-3.html","test":"/slaydlar/10-sinf-devops/hafta-03/dars-3-test.html","student_link":"/10-sinf-devops/hafta-03/dars-3","tabs":[{"g":7,"link":"/mentor/10-sinf-devops/hafta-03/dars-1","current":false},{"g":8,"link":"/mentor/10-sinf-devops/hafta-03/dars-2","current":false},{"g":9,"link":"/mentor/10-sinf-devops/hafta-03/dars-3","current":true}],"prev":{"g":8,"title":"Kompyuter tarmoqlari asoslari: OSI 7 qatlamli modeli va TCP/IP steki","link":"/mentor/10-sinf-devops/hafta-03/dars-2"},"next":null}},"headers":[],"relativePath":"mentor/10-sinf-devops/hafta-03/dars-3.md","filePath":"mentor/10-sinf-devops/hafta-03/dars-3.md"}'),h={name:"mentor/10-sinf-devops/hafta-03/dars-3.md"},c={class:"blk"},m={id:"_1-dars-konspekti-mentor-uchun",tabindex:"-1"},u={class:"blk"},k={id:"_2-amaliy-topshiriqlar-va-yechimlari-mentor-uchun",tabindex:"-1"},p={class:"blk"},g={id:"_3-tezkor-nazorat-savollari-dars-yakuni",tabindex:"-1"};function v(b,a,q,y,z,I){const o=r("Icon");return e(),d("div",null,[a[9]||(a[9]=s("<p><strong>Darsning maqsadi:</strong> O&#39;quvchilarga IPv4 manzillash arxitekturasi, ommaviy (Public) va xususiy (Private) IP diapazonlari (RFC 1918), Subnetting (qism tarmoqlar) mantig&#39;i, CIDR notatsiyasi (<code>/24</code>, <code>/16</code>), tarmoq va broadcast manzillarini hisoblash, IPv6 ning zamonaviy ahamiyati hamda server nosozliklarini aniqlashda qo&#39;llaniladigan asosiy diagnostika vositalari (<code>ping</code>, <code>traceroute</code>, <code>ss</code>, <code>curl</code>) bilan ishlashni amaliy o&#39;rgatish.</p><p><strong>Vaqt taqsimoti:</strong></p><ul><li>O&#39;tgan mavzuni takrorlash (OSI va TCP/IP steki): 10 daqiqa</li><li>Yangi mavzu: IPv4 tuzilishi, xususiy IP lar, CIDR va Subnet mask hisoblash: 25 daqiqa</li><li>Yangi mavzu: Tarmoq diagnostikasi vositalari (<code>ping</code>, <code>traceroute</code>, <code>ss</code>, <code>curl</code>): 20 daqiqa</li><li>Amaliy mashg&#39;ulot (Subnet hisoblash va serverlar o&#39;rtasida ulanishlarni diagnostika qilish): 20 daqiqa</li><li>Dars xulosasi va tezkor nazorat: 5 daqiqa</li></ul><hr>",4)),i("div",c,[i("h2",m,[t(o,{name:"file-text"}),a[0]||(a[0]=n(" 1. Dars konspekti (Mentor uchun) ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#_1-dars-konspekti-mentor-uchun","aria-label":'Permalink to "<Icon name="file-text" /> 1. Dars konspekti (Mentor uchun)"'},"​",-1))]),a[2]||(a[2]=s('<h3 id="_1-1-ipv4-manzillash-tuzilishi" tabindex="-1">1.1. IPv4 manzillash tuzilishi <a class="header-anchor" href="#_1-1-ipv4-manzillash-tuzilishi" aria-label="Permalink to &quot;1.1. IPv4 manzillash tuzilishi&quot;">​</a></h3><p>Har bir kompyuter, server yoki konteyner tarmoqda o&#39;zining noyob <strong>IP (Internet Protocol) manzili</strong> ga ega bo&#39;lishi kerak.</p><ul><li><strong>IPv4</strong>: 32 bitli ikkilik sondan iborat bo&#39;lib, o&#39;qish qulay bo&#39;lishi uchun 4 ta sakkiz bitlik bloklarga — <strong>oktet</strong>larga ajratiladi va nuqta bilan yoziladi. Masalan: <code>192.168.1.1</code> Ikkilikda: <code>11000000.10101000.00000001.00000001</code></li><li>Har bir oktet <code>0</code> dan <code>255</code> gacha bo&#39;lgan qiymatni qabul qiladi. Jami nazariy manzillar soni: $2^{32} \\approx 4.3 \\text{ milliard}$.</li></ul><h3 id="_1-2-ommaviy-public-va-xususiy-private-ip-manzillar" tabindex="-1">1.2. Ommaviy (Public) va Xususiy (Private) IP manzillar <a class="header-anchor" href="#_1-2-ommaviy-public-va-xususiy-private-ip-manzillar" aria-label="Permalink to &quot;1.2. Ommaviy (Public) va Xususiy (Private) IP manzillar&quot;">​</a></h3><p>Dunyo bo&#39;yicha IPv4 manzillari tugab qolgani sababli, <strong>RFC 1918</strong> standarti bo&#39;yicha maxsus xususiy manzillar ajratilgan:</p><ol><li><strong>A sinf</strong>: <code>10.0.0.0 – 10.255.255.255</code> (Katta korxonalar va ma&#39;lumotlar markazlari).</li><li><strong>B sinf</strong>: <code>172.16.0.0 – 172.31.255.255</code> (O&#39;rta kompaniyalar, Docker konteynerlari standart tarmog&#39;i).</li><li><strong>C sinf</strong>: <code>192.168.0.0 – 192.168.255.255</code> (Uy va kichik ofis Wi-Fi tarmoqlari). Xususiy IP lar Internetda to&#39;g&#39;ridan-to&#39;g&#39;ri marshrutlanmaydi. Ular routerdagi <strong>NAT (Network Address Translation)</strong> texnologiyasi orqali yagona ommaviy IP ga aylanib tashqariga chiqadi.</li></ol><h3 id="_1-3-subnet-mask-va-cidr-notatsiyasi" tabindex="-1">1.3. Subnet Mask va CIDR notatsiyasi <a class="header-anchor" href="#_1-3-subnet-mask-va-cidr-notatsiyasi" aria-label="Permalink to &quot;1.3. Subnet Mask va CIDR notatsiyasi&quot;">​</a></h3><p>IP manzil doimo ikki qismdan iborat: <strong>Tarmoq qismi (Network ID)</strong> va <strong>Xost qismi (Host ID)</strong>. Tarmoq qismi qayerda tugab, xost qismi qayerdan boshlanishini <strong>Subnet Mask (Tarmoq maskasi)</strong> belgilaydi.</p><ul><li>Standart maska: <code>255.255.255.0</code></li><li><strong>CIDR (Classless Inter-Domain Routing)</strong>: Maskadagi birlar (<code>1</code>) sonini ifodalovchi qisqa yozuv: <code>255.255.255.0</code> = 24 ta bir = <code>/24</code></li><li><strong>Xostlarni hisoblash formulasi</strong>: $N = 2^H - 2$ (bu yerda $H$ — xost bitlari soni, ya&#39;ni $32 - \\text{CIDR}$). Masalan, <code>/24</code> uchun: $32 - 24 = 8$ bit. Xostlar: $2^8 - 2 = 256 - 2 = \\mathbf{254 \\text{ ta}}$. <ul><li>Nega <code>-2</code> qilinadi? <ol><li>Eng birinchi manzil (<code>.0</code>) — <strong>Tarmoq manzili (Network ID)</strong> uchun band.</li><li>Eng oxirgi manzil (<code>.255</code>) — <strong>Efir manzili (Broadcast ID)</strong> uchun band.</li></ol></li></ul></li></ul><h3 id="_1-4-ipv6-ga-qisqa-nazar" tabindex="-1">1.4. IPv6 ga qisqa nazar <a class="header-anchor" href="#_1-4-ipv6-ga-qisqa-nazar" aria-label="Permalink to &quot;1.4. IPv6 ga qisqa nazar&quot;">​</a></h3><p>IPv4 tugashi muammosini hal qiluvchi 128-bitli zamonaviy manzil:</p><ul><li>Masalan: <code>2001:0db8:85a3:0000:0000:8a2e:0370:7334</code></li><li>16-lik sanoq tizimida yoziladi va ikki nuqta <code>:</code> bilan ajratiladi.</li><li>Manzillar soni $2^{128}$ ta (dunyodagi har bir qum zarrasiga milliardlab IP berishga yetadi).</li></ul><h3 id="_1-5-devops-uchun-tarmoq-diagnostikasi-vositalari" tabindex="-1">1.5. DevOps uchun tarmoq diagnostikasi vositalari <a class="header-anchor" href="#_1-5-devops-uchun-tarmoq-diagnostikasi-vositalari" aria-label="Permalink to &quot;1.5. DevOps uchun tarmoq diagnostikasi vositalari&quot;">​</a></h3><p>Serverlar orasida aloqa yo&#39;qolganda muammoni topish (troubleshooting) zanjiri:</p><ol><li><code>ping [manzil]</code> — ICMP Echo protokoli orqali masofaviy server tirikmi yoki yo&#39;qmi, paketlar yo&#39;qolishi (packet loss) va kechikish vaqti (RTT — round-trip time) ni o&#39;lchaydi: <ul><li><code>ping -c 4 8.8.8.8</code> (4 ta paket yuborish).</li></ul></li><li><code>traceroute [manzil]</code> (yoki <code>tracepath</code>) — paket masofaviy serverga yetib borguncha necha ta oraliq routerdan (hops) o&#39;tganini va qaysi routerda uzilish bo&#39;layotganini aniqlaydi (TTL asosida).</li><li><code>ss</code> (Socket Statistics) — serverdagi ochiq portlarni tekshirish: <ul><li><code>ss -tulpn</code> — TCP va UDP bo&#39;yicha qaysi jarayon qaysi portni tinglayotganini ko&#39;rsatadi.</li></ul></li><li><code>curl [URL]</code> — veb-serverga HTTP so&#39;rovi yuborish: <ul><li><code>curl -I https://google.com</code> — veb-sahifa yuklamasdan faqat HTTP status kodini (200 OK, 301, 404, 500) va sarlavhalarini ko&#39;rsatadi.</li><li><code>curl -v https://api.site.uz</code> — SSL qo&#39;l siqishi (handshake) va to&#39;liq muloqotni ko&#39;rsatadi.</li></ul></li></ol><hr>',16))]),i("div",u,[i("h2",k,[t(o,{name:"file-text"}),a[3]||(a[3]=n(" 2. Amaliy topshiriqlar va yechimlari (Mentor uchun) ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#_2-amaliy-topshiriqlar-va-yechimlari-mentor-uchun","aria-label":'Permalink to "<Icon name="file-text" /> 2. Amaliy topshiriqlar va yechimlari (Mentor uchun)"'},"​",-1))]),a[5]||(a[5]=s(`<h3 id="_1-topshiriq-internet-aloqasini-va-kechikishni-rtt-tekshirish" tabindex="-1">1-topshiriq. Internet aloqasini va kechikishni (RTT) tekshirish <a class="header-anchor" href="#_1-topshiriq-internet-aloqasini-va-kechikishni-rtt-tekshirish" aria-label="Permalink to &quot;1-topshiriq. Internet aloqasini va kechikishni (RTT) tekshirish&quot;">​</a></h3><p><code>ping</code> buyrug&#39;i yordamida Google DNS serveri (<code>8.8.8.8</code>) bilan aloqani 4 ta paket bilan tekshiring va o&#39;rtacha kechikish vaqtini aniqlang.</p><p><strong>Yechim:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">ping</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -c</span><span style="--shiki-light:#098658;--shiki-dark:#B5CEA8;"> 4</span><span style="--shiki-light:#098658;--shiki-dark:#B5CEA8;"> 8.8.8.8</span></span>
<span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;"># Natija tahlili:</span></span>
<span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;"># 4 packets transmitted, 4 received, 0% packet loss, time 3004ms</span></span>
<span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;"># rtt min/avg/max/mdev = 15.2/18.4/22.1/2.3 ms</span></span>
<span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;"># 0% paket yo&#39;qolishi va o&#39;rtacha 18.4 ms kechikish — mukammal aloqa!</span></span></code></pre></div><h3 id="_2-topshiriq-tarmoq-marshrutini-kuzatish-traceroute" tabindex="-1">2-topshiriq. Tarmoq marshrutini kuzatish (Traceroute) <a class="header-anchor" href="#_2-topshiriq-tarmoq-marshrutini-kuzatish-traceroute" aria-label="Permalink to &quot;2-topshiriq. Tarmoq marshrutini kuzatish (Traceroute)&quot;">​</a></h3><p>O&#39;z kompyuteringizdan to <code>google.com</code> gacha bo&#39;lgan yo&#39;lda necha ta oraliq tugun (router) borligini <code>tracepath</code> yoki <code>traceroute</code> bilan aniqlang.</p><p><strong>Yechim:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">tracepath</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> google.com</span></span>
<span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;"># Yoki:</span></span>
<span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">traceroute</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -n</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> google.com</span></span>
<span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;"># Chiqishda har bir router IP si va unga ketgan millisekundlar ko&#39;rinadi (odatda 8-15 ta oraliq qadam).</span></span></code></pre></div><h3 id="_3-topshiriq-veb-server-holati-va-http-statusini-tekshirish" tabindex="-1">3-topshiriq. Veb-server holati va HTTP statusini tekshirish <a class="header-anchor" href="#_3-topshiriq-veb-server-holati-va-http-statusini-tekshirish" aria-label="Permalink to &quot;3-topshiriq. Veb-server holati va HTTP statusini tekshirish&quot;">​</a></h3><p><code>curl -I</code> yordamida ommaviy veb-saytning sarlavhalarini o&#39;qing va uning javob kodini aniqlang.</p><p><strong>Yechim:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">curl</span><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;"> -I</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> https://www.google.com</span></span>
<span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;"># Natija:</span></span>
<span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;"># HTTP/2 200 (yoki 301 Moved Permanently)</span></span>
<span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;"># content-type: text/html; charset=ISO-8859-1</span></span>
<span class="line"><span style="--shiki-light:#008000;--shiki-dark:#6A9955;"># server: gws</span></span></code></pre></div><h3 id="_4-topshiriq-subnet-hisoblash-amaliyoti" tabindex="-1">4-topshiriq. Subnet hisoblash amaliyoti <a class="header-anchor" href="#_4-topshiriq-subnet-hisoblash-amaliyoti" aria-label="Permalink to &quot;4-topshiriq. Subnet hisoblash amaliyoti&quot;">​</a></h3><p>Berilgan IP manzil: <code>192.168.10.45/26</code>. Ushbu qism tarmoqning maskasini, tarmoq manzilini (Network ID), efir manzilini (Broadcast ID) va ulash mumkin bo&#39;lgan maksimal xostlar sonini hisoblang.</p><p><strong>Yechim:</strong></p><ul><li>CIDR: <code>/26</code> → 26 ta bir: <code>11111111.11111111.11111111.11000000</code></li><li>Subnet mask: <code>255.255.255.192</code></li><li>Qolgan xost bitlari soni: $32 - 26 = 6$ bit.</li><li>Maksimal xostlar soni: $2^6 - 2 = 64 - 2 = \\mathbf{62 \\text{ ta xost}}$.</li><li>Blok hajmi: 64.</li><li>Tarmoq manzillari bloklari: <code>.0</code>, <code>.64</code>, <code>.128</code>, <code>.192</code>.</li><li><code>192.168.10.45</code> birinchi blokda joylashgan: <ul><li><strong>Tarmoq manzili (Network ID)</strong>: <code>192.168.10.0</code></li><li><strong>Efir manzili (Broadcast ID)</strong>: <code>192.168.10.63</code></li><li><strong>Ishlatilishi mumkin bo&#39;lgan diapazon</strong>: <code>192.168.10.1</code> dan <code>192.168.10.62</code> gacha.</li></ul></li></ul><hr>`,17))]),i("div",p,[i("h2",g,[t(o,{name:"file-text"}),a[6]||(a[6]=n(" 3. Tezkor nazorat savollari (Dars yakuni) ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#_3-tezkor-nazorat-savollari-dars-yakuni","aria-label":'Permalink to "<Icon name="file-text" /> 3. Tezkor nazorat savollari (Dars yakuni)"'},"​",-1))]),a[8]||(a[8]=s("<ol><li><strong>RFC 1918 bo&#39;yicha xususiy (Private) IP manzillar qanday maqsadlarda ishlatiladi?</strong><em>Javob:</em> Tashkilotlar, ma&#39;lumotlar markazlari va uy tarmoqlarida ichki kompyuterlarga IP tarqatish uchun. Ular global Internetda to&#39;g&#39;ridan-to&#39;g&#39;ri ko&#39;rinmaydi va ommaviy IP manzillarni tejashga xizmat qiladi.</li><li><strong>Nima uchun har qanday qism tarmoqda (subnet) 2 ta manzil foydalanuvchilar kompyuterlariga berilmaydi?</strong><em>Javob:</em> Eng birinchi manzil butun tarmoq identifikatori (Network ID), eng oxirgi manzil esa barcha kompyuterlarga xabar yuboruvchi efir (Broadcast) uchun zaxiralangan.</li><li><strong><code>ping</code> va <code>traceroute</code> buyruqlari qaysi tarmoq protokoliga tayanib ishlaydi?</strong><em>Javob:</em> <strong>ICMP (Internet Control Message Protocol)</strong> protokoliga tayanadi.</li><li><strong><code>curl -I</code> bayrog&#39;i nima vazifani bajaradi?</strong><em>Javob:</em> Sahifaning asosiy tanasini (HTML) yuklab olmasdan, faqatgina uning HTTP sarlavhalari (Headers) va holat kodini ekranga chiqaradi.</li></ol>",1))])])}const P=l(h,[["render",v]]);export{f as __pageData,P as default};
